def choose_move(observation):
    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def best_by_distance(cands, sx, sy, reverse=False):
        best = None
        best_key = None
        for item in cands or []:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            x, y = item[0], item[1]
            d = abs(x - sx) + abs(y - sy)
            key = (d, abs(x - sx), abs(y - sy), x, y)
            if reverse:
                key = (-d, -abs(x - sx), -abs(y - sy), -x, -y)
            if best is None or key < best_key:
                best = (x, y)
                best_key = key
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            tx, ty = ox, oy
            if observation.get("opponent_visible") is False:
                tx, ty = best_by_distance(
                    [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)],
                    sx, sy
                ) or (sx, sy)
        else:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
            tx, ty = best_by_distance(corners, sx, sy, reverse=True) or (sx, sy)
        return [sign(tx - sx), sign(ty - sy)]

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or []
        )
        best = best_by_distance(targets, sx, sy)
        if best is not None:
            tx, ty = best
            return [sign(tx - sx), sign(ty - sy)]
        # Fallback: drift toward opponent side if no explicit targets
        return [sign(ox - sx), sign(oy - sy)]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = best_by_distance(resources, sx, sy)
    if best is not None:
        tx, ty = best
        return [sign(tx - sx), sign(ty - sy)]

    # Generic fallback: move toward opponent only if resource-free; otherwise stay mildly exploratory
    if abs(ox - sx) + abs(oy - sy) > 0:
        return [sign(ox - sx), sign(oy - sy)]
    return [0, 0]

